"""SQLAlchemy engine, session, and a timezone-aware UTC column type."""

from __future__ import annotations

from collections.abc import Iterator
from datetime import datetime, timezone

from sqlalchemy import DateTime, create_engine
from sqlalchemy.orm import DeclarativeBase, Session, sessionmaker

# SQLite serializes writes; a single shared connection per in-memory URL is
# required for the test suite's ``StaticPool`` setup. File-backed databases use
# the normal pool. ``check_same_thread`` is needed because FastAPI handlers run
# in worker threads.


class Base(DeclarativeBase):
    """Declarative base for all provenance models."""


class UTCDateTime(DateTime):
    """A ``DateTime`` that stores naive UTC internally on every backend.

    SQLite has no native timestamp-with-timezone type, so values are written as
    naive UTC and converted back to timezone-aware UTC on the way out. Aware
    non-UTC values are normalized to UTC first; naive values are assumed UTC.
    """

    cache_ok = True

    def __init__(self) -> None:
        super().__init__(timezone=False)

    def process_bind_param(self, value: datetime | None, dialect) -> datetime | None:
        if value is None:
            return None
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        return value.astimezone(timezone.utc).replace(tzinfo=None)

    def process_result_value(self, value: datetime | None, dialect) -> datetime | None:
        if value is None:
            return None
        return value.replace(tzinfo=timezone.utc)

    # ``process_bind_param``/``process_result_value`` are TypeDecorator hooks.
    # Subclassing DateTime directly would ignore them, so route through
    # TypeDecorator behavior by also implementing the comparator decorator API:
    # the cleanest supported way is to subclass TypeDecorator instead.


def make_engine(database_url: str):
    """Create an engine tuned for the configured database URL."""
    connect_args: dict[str, object] = {}
    kwargs: dict[str, object] = {"future": True}
    if database_url.startswith("sqlite"):
        connect_args["check_same_thread"] = False
        kwargs["connect_args"] = connect_args
        if ":memory:" in database_url or database_url.endswith("sqlite://"):
            # Keep a single connection so an in-memory schema survives across
            # sessions (used by deterministic tests).
            from sqlalchemy.pool import StaticPool

            kwargs["poolclass"] = StaticPool
    return create_engine(database_url, **kwargs)


def make_session_factory(engine) -> sessionmaker[Session]:
    return sessionmaker(bind=engine, autoflush=False, expire_on_commit=False, future=True)


def init_db(engine) -> None:
    """Create all tables. Safe and idempotent on a fresh or existing database."""
    # Import models so they are registered on ``Base.metadata`` before create.
    from provenance import models  # noqa: F401

    Base.metadata.create_all(bind=engine)


def get_session(session_factory: sessionmaker[Session]) -> Iterator[Session]:
    """FastAPI dependency yielding a session and always closing it."""
    session = session_factory()
    try:
        yield session
    finally:
        session.close()

